import{_ as o,o as a,c as r,ag as s}from"./chunks/framework.NIGIbcGl.js";const h=JSON.parse('{"title":"BlockSeat OTA Guide (Wholesale)","description":"","frontmatter":{},"headers":[],"relativePath":"customer/blockseat-ota/index.md","filePath":"customer/blockseat-ota/index.md"}'),t={name:"customer/blockseat-ota/index.md"};function c(d,e,i,n,l,p){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="blockseat-ota-guide-wholesale" tabindex="-1">BlockSeat OTA Guide (Wholesale) <a class="header-anchor" href="#blockseat-ota-guide-wholesale" aria-label="Permalink to &quot;BlockSeat OTA Guide (Wholesale)&quot;">​</a></h1><p>This guide covers the <strong>BlockSeat</strong> search + calculate endpoints. BlockSeat is <code>ota/*</code> <strong>restricted to wholesale</strong> (≥11 seated pax), priced supplier − reducer. The supplier is searched with the <strong>REAL requested passenger counts</strong> under the <strong><code>wholesale</code></strong> credential (<strong>no 1/1/1 probe</strong>), so the per-passenger fare is the actual wholesale group rate; the reducer pipeline (per-passenger allocation, whole-riyal integer floor, seat cap) then applies. The supplier returns ≥11 fares only for departures <strong>≥72h</strong> (within 72h is not searchable/bookable). Wholesale differences vs custom-OTA:</p><ul><li><strong>Reducer pricing for EVERY cabin class.</strong> Unlike custom-OTA — where BUSINESS uses markup + tax — BlockSeat prices <strong>all</strong> classes (ECONOMY <em>and</em> BUSINESS) as <code>supplier price − priceReducer</code>, sourced from the dedicated <strong>BlockSeat route-price</strong> table (separate from <code>CustomRoutePrice</code> so wholesale and promo reducers never collide).</li><li><strong><code>STANDARD</code> fares, no strikethrough.</strong> Every fare is a plain <code>STANDARD</code> fare; <code>originalFinalPrice</code> is <code>0</code> and there is no per-adult <code>originalAmount</code>.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>supplierPerPax_T = ptcfareBreakdowns[T].totalFare.amount   (raw wholesale supplier fare, real-count search ⇒ group per-pax rate)</span></span>
<span class="line"><span>perPax_T  = floor( max(0, supplierPerPax_T − priceReducer × (supplierPerPax_T / supplierPerPax_ADT)) )   (whole riyal)</span></span>
<span class="line"><span>finalPrice = Σ legs Σ pax  perPax_T × realCount            (exact sum of integer per-pax shares)</span></span>
<span class="line"><span>fare type  = &quot;STANDARD&quot;   ;   originalFinalPrice = { SAR: 0, IDR: 0, USD: 0 }   (no strikethrough)</span></span></code></pre></div><p>The <code>priceReducer</code> is an <strong>adult</strong> discount allocated across passengers by per-pax fare ratio, identical to the custom-OTA ECONOMY algorithm (<code>allocateCustomPerPax</code> REDUCER mode). A route with no active BlockSeat reducer prices at the raw supplier fare (reducer <code>0</code>), still floored per passenger. The supplier&#39;s own VAT stays inside <code>totalFare</code> (cost, not a tax we levy) — there is no HHR markup or HHR tax on a BlockSeat fare.</p><blockquote><p><strong>Host.</strong> BlockSeat is served on <code>blockseat.ahlaan.co.id</code> (custom-OTA is on <code>promo.ahlaan.co.id</code>, the main OTA on <code>tiket.ahlaan.co.id</code>). Host routing is handled by the reverse proxy (Traefik); the API itself is not host-gated.</p></blockquote><hr><h2 id="_1-search-trains" tabindex="-1">1. Search Trains <a class="header-anchor" href="#_1-search-trains" aria-label="Permalink to &quot;1. Search Trains&quot;">​</a></h2><p><code>POST /api/v1/blockseat-ota/search</code></p><p>Guards: optional auth. Throttle: 20/60s. Body is the same <code>SearchTrainDto</code> as custom-OTA (<code>origin</code>, <code>destination</code>, <code>departureDate</code>, <code>returnDate?</code>, <code>tripType</code>, <code>passengerQuantities</code>).</p><p>The supplier is searched with the <strong>real requested passenger counts</strong> (always ≥11 seated) under the <strong><code>wholesale</code></strong> credential — no 1/1/1 probe — so each fare&#39;s per-passenger rate is the actual wholesale group rate (returned for departures ≥72h). Each cabin carries a <code>bookable</code> flag: <code>false</code> when its remaining <code>availableSeats</code> cannot fit the requested seated passengers (adults + children; infants are lap). Every returned fare is a <code>STANDARD</code> fare priced supplier − reducer.</p><h2 id="_2-calculate-booking-price" tabindex="-1">2. Calculate Booking Price <a class="header-anchor" href="#_2-calculate-booking-price" aria-label="Permalink to &quot;2. Calculate Booking Price&quot;">​</a></h2><p><code>POST /api/v1/blockseat-ota/book/calculate</code></p><p>Guards: optional auth + B2B-approved. Throttle: 10/60s. Body is the same <code>CalculateBookingPriceDto</code> as custom-OTA (route + chosen <code>fareId</code> / <code>returnFareId</code> + <code>passengerQuantities</code>).</p><p>Wholesale rules enforced here (the commit step):</p><ul><li><strong>Minimum seated passengers.</strong> A request whose seated count (adults + children; infants excluded) is below the wholesale floor (default <strong>11</strong>, configurable via <code>BLOCKSEAT_MIN_PASSENGERS</code>) is rejected with <code>400</code>.</li><li><strong>Seat cap.</strong> A request whose seated count exceeds the cabin&#39;s remaining <code>availableSeats</code> is rejected with code <code>INSUFFICIENT_SEATS</code> (per leg).</li></ul><p>The response is the same shape as <code>/custom-ota/book/calculate</code> (<code>pricing.{SAR,IDR,USD}</code>, <code>trip</code>, <code>ptcFareBreakdown</code>), priced supplier − reducer for every class.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>BlockSeat reuses the unified OTA error envelope (<code>OtaErrorResponseDto</code>). Branch on <code>code</code> / <code>category</code> / <code>retryable</code>. Notable codes: below-minimum seated passengers (<code>400</code>) and <code>INSUFFICIENT_SEATS</code>.</p>`,19)])])}const g=o(t,[["render",c]]);export{h as __pageData,g as default};
